function renderModalAch(){const box=$('modal-achievements'),n=resultAch.length+resultUnlocks.length;box.hidden=!n;if(n){const label=resultAch.length&&resultUnlocks.length?'成就与新地图':resultAch.length?'成就解锁':'新地图解锁';box.innerHTML=`<small>${label}</small>${resultUnlocks.map(j=>`<span class="unlock"><i>🔓</i>${ROUTES[j].season===2&&j===8?'第二季':'第 '+(j+1)+' 关'} · ${ROUTES[j].name}</span>`).join('')}${resultAch.map(a=>`<span><i>${a.icon}</i>${a.name}</span>`).join('')}`;if(resultAch.length)sound('checkpoint');}resultAch=[];resultUnlocks=[];}
