function saveRecord(){const old=records[run.level.index],rating=rateRun(run),result={firstClear:!old?.completed,newScore:!!old?.completed&&run.score>(Number(old.score)||0),newRating:!!old?.completed&&rating>(Number(old.rating)||0),rating};records[run.level.index]={stars:Math.max(Number(old?.stars)||0,run.collected.size),score:Math.max(Number(old?.score)||0,run.score),rating:Math.max(Number(old?.rating)||0,rating),completed:true};try{localStorage.setItem('sunset-skate-v2',JSON.stringify(records));}catch{}updateRecord();return result;}
function updateRecord(){document.querySelectorAll('.route-card').forEach((card,i)=>{const locked=!isUnlocked(records,i);card.classList.toggle('locked',locked);card.querySelector('.route-lock')?.remove();if(locked){const tag=document.createElement('span');tag.className='route-lock';tag.textContent=`🔒 通关第 ${unlockRequirement(i)+1} 关解锁`;card.querySelector('.route-art').append(tag);}});const today=profile.daily[dailySeed()];$('daily-best').textContent=today?`今日最佳 ${today.distance.toLocaleString()} m`:'今日还没出发';if(run.level.daily){$('best').textContent=`今日最佳 · ${(today?.distance||0).toLocaleString()} m · 历史最远 ${bestDaily(profile).toLocaleString()} m`;return;}const r=records[run.level.index];$('best').textContent=r?.completed?`个人最佳 · ${stars3(Math.max(1,Number(r.rating)||1))} · ${Number(r.score)||0} 分 · ${Number(r.stars)||0} / ${run.level.stars.length} 星`:'个人最佳 · 等你创造';document.querySelectorAll('.route-record').forEach((e,i)=>{const rec=records[i];e.textContent=rec?.completed?`${stars3(Math.max(1,Number(rec.rating)||1))} · ${(Number(rec.score)||0).toLocaleString()}`:'';e.title=rec?.completed?`最高 ${Number(rec.score)||0} 分 · ${Number(rec.stars)||0} 颗星星`:'';});const done=ROUTES.filter((_,i)=>records[i]?.completed).length,rated=ROUTES.reduce((sum,_,i)=>sum+(records[i]?.completed?Math.max(1,Number(records[i].rating)||1):0),0);$('route-summary').textContent=done?`已通关 ${done} / ${ROUTES.length} · 评星 ${rated} / ${ROUTES.length*3}`:`第 1–${ROUTES.length} 关 · 从易到难`;}
function sound(type){if(!soundOn)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const tones={jump:[250,500,.12],star:[780,1200,.12],land:[110,60,.07],crash:[190,45,.28],checkpoint:[600,900,.24],win:[500,1400,.6],grind:[180,700,.25],spring:[200,900,.3],boost:[300,800,.2],ring:[900,1500,.15],airjump:[420,820,.1],item:[700,1300,.25],shield:[1200,300,.3]};const [a,b,d]=tones[type]||tones.star;const osc=audio.createOscillator(),gain=audio.createGain();osc.type=type==='crash'?'sawtooth':'sine';osc.frequency.setValueAtTime(a,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(b,audio.currentTime+d);gain.gain.setValueAtTime(.07,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+d);}catch{}}
function toast(message,duration=2200){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),duration);}
function updateHud(){
 const place=Math.min(2,Math.floor(run.progress*3));document.querySelectorAll('.journey-stop').forEach((e,i)=>{e.classList.toggle('current',i===place);e.classList.toggle('passed',i<place);if(i===place)e.setAttribute('aria-current','step');else e.removeAttribute('aria-current');});
 $('stars').textContent=String(run.collected.size).padStart(2,'0');$('distance').textContent=Math.floor(run.progress*run.level.length/10);$('progress-fill').style.width=`${run.progress*100}%`;$('charge-fill').style.width=`${run.charge*100}%`;
 $('charge-label').textContent=run.brakeHeld&&run.grounded?(run.speed<5?'已停稳 · 绿灯松开刹车':'刹车中 · 留出停车距离'):run.grinding?'滑杆中 · 可再次起跳':run.sliding?'压低身体 · 通过再松手':run.holding?(run.charge>=1?'蓄力满了，松开！':'蓄力中… 松开起跳'):'轻点小跳 · 长按蓄力';$('jump').classList.toggle('charging',run.holding);$('slide').classList.toggle('active',run.duckHeld);$('brake').classList.toggle('active',run.brakeHeld);
 const playing=run.state==='playing',next=run.nextAction;$('game-shell').classList.toggle('playing',playing);$('flow').hidden=!playing;$('combo').textContent=`× ${run.combo}`;$('score').textContent=`${run.score.toLocaleString()} 分`;$('action-cue').hidden=!playing||!next;
 if(next){const labels={jump:['↑','跳过路障','空格 / 跳跃'],gap:['↗','前方断崖','提前蓄力，再松开'],slide:['↓','低头滑过去','按住 ↓ / S / 滑行'],rail:['↗','跳上栏杆','从上方落下，自动滑杆'],grinding:['✦','滑杆中！','滑到底加分 · 可再次起跳'],transfer:['↗','杆尾前，再跳一次！','长按蓄力，接到下一根杆']};labels.tire=['↔','跳过滚动轮胎','看准移动位置 · 再起跳'];labels.spring=['⤒','踩上弹簧板','自动弹射 · 越过高墙和断崖'];labels.boost=['»','冲上加速带','加速时蓄力起跳，飞得更远'];labels.ring=['◎','空中跳环','碰到光环后轻点跳跃，再跳一次'];labels.glide=run.gliding?['≋','滑翔中',run.jumpHeld?'按住上升 · 松开缓降':'松开缓降 · 按住上升']:['≋','上升气流','跳进去后按住跳跃上升'];labels.swing=['↓','低头躲摆锤','按住滑行 · 也可刹车等它摆开'];labels.shutter=next.open&&next.remaining>.7?['→','绿灯，松开刹车',`还可通行 ${next.remaining.toFixed(1)} 秒 · 不要跳`]:['Ⅱ',next.open?'闸门将关，先刹车':'红灯，刹车等待','按住 ← / A / 刹车，等绿灯'];const [icon,title,detail]=labels[next.kind];$('cue-icon').textContent=icon;$('cue-title').textContent=title;$('cue-detail').textContent=next.distance>0?`${next.distance} m · ${detail}`:detail;$('action-cue').dataset.kind=next.kind;}
}
function hideModal(){$('modal').hidden=true;}
function showModal({eyebrow,title,copy,primary,secondary,action,second,stats=false,badge=''}){clearResultTimer();run.cancelInput();const resultPose=run.state==='crashed'?'crash':run.state==='won'?'win':null;$('modal-expression').hidden=!resultPose;if(resultPose&&charactersReady)paintPortrait($('modal-expression'),selectedCharacter,resultPose);$('modal-eyebrow').textContent=eyebrow;$('modal-title').textContent=title;$('modal-copy').textContent=copy;$('modal-primary').textContent=primary;$('modal-secondary').textContent=secondary;modalAction=action;secondaryAction=second;$('result-stats').hidden=!stats;if(typeof stats==='string')$('result-stats').innerHTML=stats;else if(stats)$('result-stats').innerHTML=`<div class="result-rating"><b aria-label="评星 ${rateRun(run)} / 3">${stars3(rateRun(run))}</b>${badge?`<em>${badge}</em>`:''}</div><div><b>${run.score.toLocaleString()}</b><span>动作总分</span></div><div><b>${run.collected.size}<small>/${run.level.stars.length}</small></b><span>收集星星</span></div><div><b>×${run.maxCombo}</b><span>最高连击</span></div><div><b>${run.deaths}</b><span>摔倒次数</span></div><div><b>${Math.round(run.grindDistance/10)}m</b><span>滑杆距离</span></div>`;renderModalAch();$('modal').hidden=false;$('play-controls').hidden=true;$('pause').disabled=true;hideCoach();requestAnimationFrame(()=>$('modal-primary').focus({preventScroll:true}));}
function revealShell(){if(document.fullscreenElement)return;const el=$('game-shell'),r=el.getBoundingClientRect(),vh=innerHeight;if(r.top<-1||r.bottom>vh+1)el.scrollIntoView({behavior:reducedMotion()?'instant':'smooth',block:r.height>=vh-8?'start':'center'});}
function unlockFx(){if(!soundOn)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();}catch{}}
function start(){if(!run.level.daily&&!isUnlocked(records,run.level.index)){const i=run.level.index;const need=unlockRequirement(i);toast(`先通关第 ${need+1} 关「${ROUTES[need].name}」，这里就解锁了`);return;}clearResultTimer();music.play();unlockFx();revealShell();resultAch=[];resultUnlocks=[];coach=null;taught.clear();hideCoach();hideModal();run.reset();run.start();art=new Art(selectedCharacter);art.camera=0;accumulator=0;profile.totals.runs++;beginCountdown(1.8);$('cover').hidden=true;$('play-controls').hidden=false;$('pause').disabled=false;$('start').blur();countdownToast=[run.level.daily?'一条命 · 越滑越快 · 能滑多远？':run.level.season===2?run.level.description:run.level.movers?.length?'空格跳跃 · ↓ 低头 · ← / A 刹车等时机':'空格跳跃 · ↓ 低头 · 落到栏杆上自动滑杆',3200];updateHud();}
function retry(){clearResultTimer();music.play();unlockFx();run.retry();coach=null;hideCoach();resultAch=[];beginCountdown(.8,'READY');art.camera=Math.max(0,run.x-200);art.particles=[];art.popups=[];art.shake=0;accumulator=0;hideModal();$('play-controls').hidden=false;$('pause').disabled=false;countdownToast=[run.checkpoint.x>160?'从检查点出发 · 再来一次':'慢慢来，起跳前留一点距离'];$('modal-primary').blur();}
