function pause(){if(countdown>0)return;if(run.state==='paused'){resume();return;}if(run.state!=='playing')return;run.pause();music.pause();saveProfile();showModal({eyebrow:'TAKE A BREATHER',title:'风景值得慢一点。',copy:'你的滑板就在这里，准备好再出发。',primary:'继续滑行 →',secondary:'重新开始这条路线',action:resume,second:start});}
