function chooseCharacter(id){selectedCharacter=characterFor(id).id;art.character=selectedCharacter;document.querySelectorAll('.character-choice').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.character===selectedCharacter)));$('character-status').textContent=`当前角色：${characterFor(id).name}`;try{localStorage.setItem('sunset-character',selectedCharacter);}catch{}renderExpressions();if(charactersReady&&!$('modal-expression').hidden)paintPortrait($('modal-expression'),selectedCharacter,run.state==='crashed'?'crash':'win');}
document.querySelectorAll('.character-choice').forEach(button=>{button.onclick=()=>{chooseCharacter(button.dataset.character);button.blur();};});chooseCharacter(selectedCharacter);
$('expression-grid').innerHTML=POSES.map(p=>`<figure><canvas data-expression="${p.id}" aria-label="${p.name}"></canvas><figcaption><b>${p.name}</b><span>${p.emotion}</span></figcaption></figure>`).join('');
$('expressions-open').onclick=()=>{if(run.state==='playing')pause();renderExpressions();$('expressions').showModal();};$('expressions-close').onclick=()=>$('expressions').close();document.querySelectorAll('[data-gallery-character]').forEach(button=>button.onclick=()=>chooseCharacter(button.dataset.galleryCharacter));
selectRoute(0);
$('start').disabled=true;
if(!window.Phaser){$('start').textContent='引擎未加载，请刷新重试';$('start').disabled=true;}else loadCharacters().then(()=>{charactersReady=true;document.querySelectorAll('[data-character-portrait]').forEach(canvas=>paintPortrait(canvas,canvas.dataset.characterPortrait,'ride'));renderExpressions();$('expressions-open').disabled=false;engineReady=true;game=new Phaser.Game({type:Phaser.CANVAS,parent:'game',backgroundColor:'#f7ce9c',transparent:true,clearBeforeRender:false,banner:false,audio:{noAudio:true},scale:{mode:Phaser.Scale.NONE,width:Math.max(1,Math.round($('game').clientWidth*pixelRatio)),height:Math.max(1,Math.round($('game').clientHeight*pixelRatio))},scene:CoastScene,disableContextMenu:true,fps:{target:60},input:{activePointers:2}});refreshStart();}).catch(()=>{$('start').textContent='角色加载失败，点击重试';$('start').disabled=false;$('start').onclick=()=>location.reload();});
